def norm(t): return re.sub(r'[^a-z0-9 ]', '', (t or '').lower().replace('’', "'"))
def evora_ann(r):
    k = norm(r["eff_title"]) + " " + norm((r["eff_body"] or "")[:200])
    for pat, a in EVORA:
        if re.search(pat, k): return a
    return A("unclassified", "", "", "", "", "", "", "", "")
def status(r):
    e = r.get("end_date") or ""
    if e >= "2026-10-02": return f"ACTIVE (library end_date {e} = still delivering)"
    return f"listed active but last delivery {e} (likely paused/stopped)"
def ev_strength(r):
    ids, pages, col, d = r["concept_ids_in_sample"], len(r["concept_pages_in_sample"]), r["concept_collation_sum"], r["days_running"] or 0
    live = (r.get("end_date") or "") >= "2026-10-02"
    sig = []
    if d >= 60: sig.append(f"longevity {d}d")
    if ids >= 10: sig.append(f"concept replicated in {ids} ad IDs")
    if pages >= 2: sig.append(f"cross-page ({pages} pages)")
    if (r.get("collation_count") or 1) >= 3: sig.append(f"{r['collation_count']} ads use this creative")
    if live: sig.append("still live")
    long_ = d >= 60
    other = len([s for s in sig if not s.startswith(("still", "longevity"))])
    if long_ and other >= 1: lvl = "HIGH" if live else f"HIGH-historical (now stopped; last delivery {r.get('end_date')})"
    elif other >= 3 and live: lvl = "HIGH (concept-level; this ad ID is <60d)"
    elif (long_ or other >= 1) and live: lvl = "MEDIUM"
    elif long_ or other >= 2: lvl = "MEDIUM (not currently delivering)"
    else: lvl = "LOW"
    return f"{lvl}: " + ("; ".join(sig) if sig else "single observation") + f" [concept: {ids} IDs / {pages} page(s) / collation sum {col} in our sample]"
def first_line(b):
    for l in (b or "").split("\n"):
        l = l.strip().strip("⠀").strip()
        if l: return l
    return ""
def excerpt(b, n=320):
    b = (b or "").replace("\r", "")
    return b if len(b) <= n else b[:n] + " [...]"
