cols = ["ad_id","source","page_name","brand/domain","status","start_date","days_running","variant_count","format","hook","headline","body_excerpt","angle","desire","problem_framing","mechanism","promise_claim","awareness_level","big_idea","story_structure","cta_offer","visual_pattern","landing_url","landing_page_pattern","evidence_strength","notes"]
with open(D + "/swipe_ledger.csv", "w", newline="") as f:
    w = csv.DictWriter(f, fieldnames=cols); w.writeheader()
    for r in rows:
        isev = r["domain"] in ("evorabody.com", "skinglowmagazine.com")
        a = dict(evora_ann(r) if isev else COMP.get(r["brand"], COMP[""]))
        if r["ad_archive_id"] in OVR: a.update({k: v for k, v in OVR[r["ad_archive_id"]].items() if k in a})
        vis = a["visual_default"] or ""
        fmt = r["display_format"] or "unknown"
        if r["ad_archive_id"] in vis: vis = f"[{fmt}] THIS AD VIEWED. " + vis
        elif r["ad_archive_id"] in VIEWED: vis = f"[{fmt}] thumbnail downloaded (thumbs/{r['ad_archive_id']}.jpg) but not individually described. Concept examples: " + (vis or "n/a")
        elif vis and vis not in ("not viewed", "Text-only"): vis = f"[{fmt}] This ad not viewed. Concept examples viewed: " + vis
        else: vis = f"[{fmt}] not viewed" if vis != "Text-only" else "Text-only (no media)"
        ld = (r.get("link_description") or "").strip()
        if "{{" in ld: ld = ""
        cta = f"CTA button: {r.get('cta_text') or 'none'}" + (f" | link description: {ld}" if ld else "")
        brand = r["brand"] or "unknown (no landing URL)"
        notes = []
        if r["display_format"] == "DCO": notes.append("DCO ad: copy taken from first dynamic card")
        if "es.evorabody" in r["eff_link"] or "/es/" in r["eff_link"]: notes.append("Spanish-language variant for US Hispanic audience")
        if r["page_name"] not in ("Evora Body",) and isev: notes.append(f"Persona/advertorial page linking to {r['domain']}")
        if r["brand"] == "Goda" and r["page_name"] != "Goda Perfume": notes.append("Goda persona page")
        if r["page_name"] == "Joanna Woodley": notes.append("Advertiser/brand not identifiable from library record (no link); 75 active ads on this page per library count")
        notes.append(f"days_since_start_asof_2026-10-03={r['days_since_start_asof_2026-10-03']}; surfaced by: {', '.join(sorted(set(r['sources'])))}")
        w.writerow({"ad_id": r["ad_archive_id"], "source": "Meta Ad Library (US, public, logged-out)", "page_name": r["page_name"].strip(),
            "brand/domain": f"{brand} / {r['domain'] or '-'}", "status": status(r), "start_date": r["start_date"],
            "days_running": r["days_running"], "variant_count": f"{r.get('collation_count') or 1} (library 'ads use this creative'); concept IDs in sample: {r['concept_ids_in_sample']} across {len(r['concept_pages_in_sample'])} page(s)",
            "format": r["display_format"], "hook": first_line(r["eff_body"]) or "(no primary text)", "headline": r["eff_title"] or "(none)",
            "body_excerpt": excerpt(r["eff_body"]), "angle": a["angle"], "desire": a["desire"], "problem_framing": a["problem_framing"],
            "mechanism": a["mechanism"], "promise_claim": a["promise_claim"], "awareness_level": a["awareness_level"], "big_idea": a["big_idea"],
            "story_structure": a["story_structure"], "cta_offer": cta, "visual_pattern": vis, "landing_url": r["eff_link"],
            "landing_page_pattern": lp(r["eff_link"]), "evidence_strength": ev_strength(r), "notes": " | ".join(notes)})
